      if (document.body.classList.contains("playback-ready")) {
        openTour(true, playbackTourSteps, PLAYBACK_TOUR_STORAGE_KEY);
      } else {
        openTour(true, startTourSteps, TOUR_STORAGE_KEY);
      }
    });
  }

  window.addEventListener("keydown", (event) => {
